function search(nums, target):
    low = 0
    high = nums.length - 1

    while low <= high:
        mid = low + (high - low) / 2
        if nums[mid] == target:
            return mid

        // Check if left half is sorted
        if nums[low] <= nums[mid]:
            if nums[low] <= target && target < nums[mid]:
                high = mid - 1
            else:
                low = mid + 1
        // Right half must be sorted
        else:
            if nums[mid] < target && target <= nums[high]:
                low = mid + 1
            else:
                high = mid - 1
    return -1
